/**
 * Chart scales the kit's value charts share (TrendChart's `scale="value"`, the
 * Portfolio's value chart): the domain comes from the value line only, its
 * round ticks bracket it and the top tick is labelled, so the line fills the
 * plot and its movement reads. A second series (the money invested) far below
 * or above the value is not drawn at the plot's edge: `off` says where it is,
 * and the chart names it in its legend instead.
 */

/** The plot's height in its own units, with the room kept above and below. */
export interface ScaleFrame {
  height: number;
  top: number;
  bottom: number;
}

export interface BracketScale {
  lo: number;
  hi: number;
  ticks: number[];
  step: number;
  y: (v: number) => number;
}

/**
 * A Y scale whose round ticks bracket the data: the lowest tick at or below
 * the smallest value, the highest at or above the largest, and the domain is
 * exactly that tick range, so the top tick is labelled and the line fills the
 * plot. The data gets a 4% margin first (the line never sits on the edge),
 * then the step (1, 2, 2.5, 3, 4 or 5 of a power of ten) that gives 3 to 6
 * ticks with the least empty space wins.
 */
export function bracketScale(min: number, max: number, f: ScaleFrame): BracketScale {
  const span = max - min || Math.abs(max) * 0.02 || 1;
  const a = min - span * 0.04;
  const b = max + span * 0.04;
  const mag = Math.pow(10, Math.floor(Math.log10(b - a)));
  let best: { lo: number; hi: number; step: number; n: number } | null = null;
  for (const m of [0.1, 0.2, 0.25, 0.3, 0.4, 0.5, 1, 2, 2.5, 3, 4, 5, 10]) {
    const step = m * mag;
    const lo = Math.floor(a / step + 1e-9) * step;
    const hi = Math.ceil(b / step - 1e-9) * step;
    const n = Math.round((hi - lo) / step) + 1;
    if (n < 3 || n > 6) continue;
    if (!best || hi - lo < best.hi - best.lo - 1e-9 || (Math.abs(hi - lo - (best.hi - best.lo)) <= 1e-9 && n < best.n)) best = { lo, hi, step, n };
  }
  const { lo, hi, step, n } = best ?? { lo: a, hi: b, step: (b - a) / 2, n: 3 };
  const ticks = Array.from({ length: n }, (_, i) => Number((lo + i * step).toPrecision(12)));
  const top = f.top;
  const bottom = f.height - f.bottom;
  return { lo, hi, ticks, step, y: (v: number) => bottom - ((v - lo) / (hi - lo)) * (bottom - top) };
}

export type OffRange = 'below' | 'above' | null;

/**
 * The value-led scale: bracketed on `values` alone. A `second` series wholly
 * below or above that range is left off (`off` says which side); one that is
 * partly inside is taken into the range, so it is drawn whole.
 */
export function valueScale(values: readonly number[], second: readonly number[], f: ScaleFrame): { scale: BracketScale; off: OffRange } {
  const v = values.filter(Number.isFinite);
  const s = second.filter(Number.isFinite);
  let scale = bracketScale(Math.min(...v), Math.max(...v), f);
  const below = s.length > 0 && s.every((x) => x < scale.lo);
  const above = s.length > 0 && s.every((x) => x > scale.hi);
  if (s.length && !below && !above && s.some((x) => x < scale.lo || x > scale.hi)) scale = bracketScale(Math.min(...v, ...s), Math.max(...v, ...s), f);
  return { scale, off: below ? 'below' : above ? 'above' : null };
}
